{
  "name": "infisical-auth-action",
  "version": "1.0.7",
  "description": "Github action to authenticate with Infisical",
  "main": "lib/index.js",
  "type": "module",
  "scripts": {
    "build": "rollup --config rollup.config.js",
    "format-check": "prettier --check '**/*.js' --ignore-path ./dist/**"
  },
  "bugs": {
    "url": "https://github.com/Infisical/auth-action/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Infisical/auth-action"
  },
  "keywords": [],
  "author": "Infisical",
  "license": "ISC",
  "dependencies": {
    "@actions/core": "^1.10.1",
    "@aws-crypto/sha256-js": "^5.2.0",
    "@aws-sdk/credential-providers": "^3.758.0",
    "@aws-sdk/protocol-http": "^3.370.0",
    "@aws-sdk/signature-v4": "^3.370.0",
    "axios": "^1.6.8"
  },
  "devDependencies": {
    "@rollup/plugin-commonjs": "^28.0.6",
    "@rollup/plugin-json": "^6.1.0",
    "@rollup/plugin-node-resolve": "^16.0.1",
    "@rollup/plugin-typescript": "^12.1.4",
    "@types/node": "^24.5.2",
    "prettier": "^3.6.2",
