import commonjs from "@rollup/plugin-commonjs";
import { nodeResolve } from "@rollup/plugin-node-resolve";
import json from "@rollup/plugin-json";
import typescript from "@rollup/plugin-typescript";

/** @type {import('rollup').RollupOptions} */
const config = {
  input: "src/index.ts",
  output: {
    esModule: false,
    inlineDynamicImports: true,
    file: "dist/index.cjs",
    format: "cjs",
    sourcemap: true,
    banner: "#!/usr/bin/env node",
  },
  plugins: [
    typescript({
      declaration: false,
      tsconfig: "./tsconfig.json"
    }),
    commonjs(),
    nodeResolve({ preferBuiltins: true }),
    json()
  ],
}

export default config;

import axios from "axios";
import core from "@actions/core";
import fs from "fs/promises";
import { AxiosError } from "axios";
import { AuthMethod } from "./constants";

export const createAxiosInstance = (
  domain: string,
  defaultHeaders?: Record<string, string>,
) => {
  const instance = axios.create({
    baseURL: domain,
    ...(defaultHeaders && { headers: defaultHeaders }),
  });

  return instance;
};

export const handleRequestError = (err: unknown) => {
  if (err instanceof AxiosError) {
    core.error(err.response?.data?.message);
    if (typeof err?.response?.data === "object") {
      core.error(JSON.stringify(err?.response?.data, null, 4));
    }
  } else {
    core.error((err as Error)?.message);
  }
};

export const validateAuthMethod = (authMethod: string) => {
  if (!Object.values(AuthMethod).includes(authMethod as AuthMethod)) {
    throw new Error(`Invalid auth method: ${authMethod}`);
  }
};

export const exportAccessToken = async (
  infisicalToken: string,
  outputCredential: boolean,
  outputEnvCredential: boolean,
) => {
  core.setSecret(infisicalToken);

  if (outputCredential) {
    core.setOutput("access-token", infisicalToken);
    core.info("Set Infisical token as action output [access-token]");
  }

  if (outputEnvCredential) {
    core.exportVariable("INFISICAL_TOKEN", infisicalToken);
    core.info(
      "Injected Infisical token as environment variable [INFISICAL_TOKEN]",
    );
  }
};

export const AWS_TOKEN_METADATA_URI = "http://169.254.169.254/latest/api/token";
export const AWS_IDENTITY_DOCUMENT_URI =
  "http://169.254.169.254/latest/dynamic/instance-identity/document";

export enum AuthMethod {
  Universal = "universal",
  Oidc = "oidc",
  AwsIam = "aws-iam",
}

export const ENVIRONMENT_VARIABLE_NAMES = {
  INFISICAL_UNIVERSAL_AUTH_CLIENT_ID_NAME: "INFISICAL_UNIVERSAL_AUTH_CLIENT_ID",
  INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET_NAME:
    "INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET",
  INFISICAL_MACHINE_IDENTITY_ID_NAME: "INFISICAL_MACHINE_IDENTITY_ID",
} as const;

export type EnvironmentVariableNames =
  (typeof ENVIRONMENT_VARIABLE_NAMES)[keyof typeof ENVIRONMENT_VARIABLE_NAMES];

import axios, { AxiosError, AxiosInstance } from "axios";
import core from "@actions/core";
import querystring from "querystring";
import { Sha256 } from "@aws-crypto/sha256-js";
import { fromNodeProviderChain } from "@aws-sdk/credential-providers";
import { HttpRequest } from "@aws-sdk/protocol-http";
import { SignatureV4 } from "@aws-sdk/signature-v4";
import {
  AuthMethod,
  AWS_IDENTITY_DOCUMENT_URI,
  AWS_TOKEN_METADATA_URI,
} from "./constants";
import { TIdentityLoginResponse, TPerformAuth } from "./types";
import { handleRequestError } from "./util";

export const authenticationFactory = ({
  domain,
  defaultHeaders,
}: {
  domain: string;
  defaultHeaders?: Record<string, string>;
}) => {
  const request = axios.create({
    baseURL: domain,
    ...(defaultHeaders && { headers: defaultHeaders }),
  });

  const login = async (data: TPerformAuth) => {
    switch (data.method) {
      case AuthMethod.Universal:
        return $universalAuthLogin(data);
      case AuthMethod.Oidc:
        return $oidcLogin(data);
      case AuthMethod.AwsIam:
        return $awsIamLogin(data);
      default:
        throw new Error(
          `Invalid authentication method: ${(data as unknown as { method: string })?.method ?? "Unknown"}`,
        );
    }
  };

  const $universalAuthLogin = async ({
    clientId,
    clientSecret,
  }: {
    clientId: string;
    clientSecret: string;
  }) => {
    const loginData = querystring.stringify({
      clientId,
      clientSecret,
    });

    try {
      const response = await request<TIdentityLoginResponse>({
        method: "post",
        url: "/api/v1/auth/universal-auth/login",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        data: loginData,
      });

      return response.data.accessToken;
    } catch (err) {
      handleRequestError(err);
      throw err;
    }
  };

  const $oidcLogin = async ({
    identityId,
    oidcAudience,
  }: {
    identityId: string;
    oidcAudience?: string;
  }) => {
    const idToken = await core.getIDToken(oidcAudience);

    const loginData = querystring.stringify({
      identityId,
      jwt: idToken,
    });

    try {
      const response = await request<TIdentityLoginResponse>({
        method: "post",
        url: "/api/v1/auth/oidc-auth/login",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        data: loginData,
      });

      return response.data.accessToken;
    } catch (err) {
      handleRequestError(err);
      throw err;
    }
  };

  const $awsIamLogin = async ({ identityId }: { identityId: string }) => {
    try {
      // Get AWS region
      const region = await getAwsRegion();

      // Get AWS credentials
      const credentials = await fromNodeProviderChain()();

      if (!credentials.accessKeyId || !credentials.secretAccessKey) {
        throw new Error("AWS credentials not found");
      }

      // Create the AWS STS request
      const iamRequestURL = `https://sts.${region}.amazonaws.com/`;
      const iamRequestBody = "Action=GetCallerIdentity&Version=2011-06-15";
      const iamRequestHeaders = {
        "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
        Host: `sts.${region}.amazonaws.com`,
      };

      const awsRequest = new HttpRequest({
        protocol: "https:",
        hostname: `sts.${region}.amazonaws.com`,
        path: "/",
        method: "POST",
        headers: {
          ...iamRequestHeaders,
          "Content-Length": String(Buffer.byteLength(iamRequestBody)),
        },
        body: iamRequestBody,
      });

      // Sign the request
      const signer = new SignatureV4({
        credentials,
        region,
        service: "sts",
        sha256: Sha256,
      });

      const signedRequest = await signer.sign(awsRequest);

      // Extract headers as string record
      const headers: Record<string, string> = {};
      Object.entries(signedRequest.headers).forEach(([key, value]) => {
        if (typeof value === "string") {
          // Normalize Authorization header to proper case
          const normalizedKey =
            key.toLowerCase() === "authorization" ? "Authorization" : key;
          headers[normalizedKey] = value;
        }
      });

      // Send login request to Infisical
      const loginData = querystring.stringify({
        identityId,
        iamHttpRequestMethod: "POST",
        iamRequestBody: Buffer.from(iamRequestBody).toString("base64"),
        iamRequestHeaders: Buffer.from(JSON.stringify(headers)).toString(
          "base64",
        ),
      });

      const response = await request<TIdentityLoginResponse>({
        method: "post",
        url: "/api/v1/auth/aws-auth/login",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        data: loginData,
      });

      return response.data.accessToken;
    } catch (err) {
      handleRequestError(err);
      throw err;
    }
  };

  return {
    login,
  };
};

const getAwsRegion = async () => {
  const region = process.env.AWS_REGION; // Typically found in lambda runtime environment
  if (region) {
    return region;
  }

  try {
    const tokenResponse = await axios.put(AWS_TOKEN_METADATA_URI, undefined, {
      headers: {
        "X-aws-ec2-metadata-token-ttl-seconds": "21600",
      },
      timeout: 5_000, // 5 seconds
    });

    const identityResponse = await axios.get(AWS_IDENTITY_DOCUMENT_URI, {
      headers: {
        "X-aws-ec2-metadata-token": [REDACTED],
        Accept: "application/json",
      },
      timeout: 5_000, // 5 seconds
    });

    return identityResponse.data.region;
  } catch (err) {
    handleRequestError(err);
    throw err;
  }
};

import core from "@actions/core";
import { authenticationFactory } from "./infisical";
import {
  AuthMethod,
  ENVIRONMENT_VARIABLE_NAMES,
  EnvironmentVariableNames,
} from "./constants";
import { exportAccessToken, validateAuthMethod } from "./util";
import { TPerformAuth } from "./types";

function parseHeadersInput(inputKey: string) {
  const rawHeadersString = core.getInput(inputKey) || "";

  const headerStrings = rawHeadersString
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line !== "");

  const parsedHeaderStrings = headerStrings.reduce(
    (obj, line) => {
      const separator = line.indexOf(":");
      const key = line.substring(0, separator).trim().toLowerCase();
      const value = line.substring(separator + 1).trim();
      if (obj[key]) {
        obj[key] = [obj[key], value].join(", ");
      } else {
        obj[key] = value;
      }
      return obj;
    },
    {} as Record<string, string>,
  );

  return parsedHeaderStrings;
}

const getInput = (
  coreInputKey: string,
  environmentVariableName: EnvironmentVariableNames,
) => {
  try {
    const input = core.getInput(coreInputKey);
    if (input) {
      return input;
    }

    const environmentVariable = process.env[environmentVariableName];
    if (environmentVariable) {
      return environmentVariable;
    }

    return null;
  } catch (err) {
    core.debug(
      `Error getting input ${coreInputKey}: ${(err as Error)?.message}`,
    );
    return null;
  }
};

const main = async () => {
  try {
    const method = core.getInput("method");
    const domain = core.getInput("domain");
    const outputCredential = core.getBooleanInput("output-credential");
    const outputEnvCredential = core.getBooleanInput("output-env-credential");
    const extraHeaders = parseHeadersInput("extra-headers");

    validateAuthMethod(method);

    let performAuth: TPerformAuth;

    switch (method) {
      case AuthMethod.Universal: {
        const uaClientId = getInput(
          "client-id",
          ENVIRONMENT_VARIABLE_NAMES.INFISICAL_UNIVERSAL_AUTH_CLIENT_ID_NAME,
        );
        const uaClientSecret = getInput(
          "client-secret",
          ENVIRONMENT_VARIABLE_NAMES.INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET_NAME,
        );

        if (!uaClientId || !uaClientSecret) {
          throw new Error("Missing Universal Auth credentials");
        }

        performAuth = {
          method: AuthMethod.Universal,
          clientId: uaClientId,
          clientSecret: [REDACTED],
        };
        break;
      }
      case AuthMethod.Oidc: {
        const identityId = getInput(
          "identity-id",
          ENVIRONMENT_VARIABLE_NAMES.INFISICAL_MACHINE_IDENTITY_ID_NAME,
        );
        const oidcAudience = core.getInput("oidc-audience");

        if (!identityId) {
          throw new Error("Missing identity ID for OIDC auth");
        }

        performAuth = {
          method: AuthMethod.Oidc,
          identityId,
          oidcAudience,
        };
        break;
      }
      case AuthMethod.AwsIam: {
        const identityId = getInput(
          "identity-id",
          ENVIRONMENT_VARIABLE_NAMES.INFISICAL_MACHINE_IDENTITY_ID_NAME,
        );

        if (!identityId) {
          throw new Error("Missing identity ID for AWS IAM auth");
        }

        performAuth = {
          method: AuthMethod.AwsIam,
          identityId,
        };
        break;
      }
      default:
        throw new Error(`Invalid authentication method: ${method}`);
    }

    const auth = authenticationFactory({
      domain,
      defaultHeaders: extraHeaders,
    });

    const infisicalToken = await auth.login(performAuth);

    await exportAccessToken(
      infisicalToken,
      outputCredential,
      outputEnvCredential,
    );
  } catch (err) {
    core.setFailed((err as Error)?.message);
  }
};

main();

import { AuthMethod } from "./constants";

export type TPerformAuth =
  | {
      method: AuthMethod.Universal;
      clientId: string;
      clientSecret: string;
    }
  | {
      method: AuthMethod.Oidc;
      identityId: string;
      oidcAudience?: string;
    }
  | {
      method: AuthMethod.AwsIam;
      identityId: string;
    };

export type TIdentityLoginResponse = {
  accessToken: string;
};
